// Expo config plugin: release build optimizations.
//
// `android/` is generated by `expo prebuild` and is gitignored in this repo, so
// release settings cannot be committed there directly. This plugin is the
// tracked source of truth: it is applied on every prebuild and mirrors exactly
// what is committed by hand in the local (ignored) android/ directory.
//
// It does three things:
//   1. Enables R8 minification + resource shrinking for release builds.
//   2. Switches build.gradle from proguard-android.txt to proguard-android-optimize.txt
//      to enable full R8 code optimizations and satisfy Google Play DEX thresholds.
//   3. Maintains a clearly-marked block of ProGuard keep rules in
//      android/app/proguard-rules.pro (appended after any existing content).

const fs = require('fs');
const path = require('path');
const { withGradleProperties, withDangerousMod, withAppBuildGradle } = require('expo/config-plugins');

const GRADLE_PROPERTIES = {
  'android.enableMinifyInReleaseBuilds': 'true',
  'android.enableShrinkResourcesInReleaseBuilds': 'true',
};

const MARKER_START = '# >>> spendsense release optimization keep rules >>>';
const MARKER_END = '# <<< spendsense release optimization keep rules <<<';

// Each rule is here because the class is reached reflectively / by name at
// runtime (JNI, view-manager registry, fragment recreation) and R8 would
// otherwise rename or strip it in a minified release build.
const KEEP_RULES = `${MARKER_START}
# Native methods and DoNotStrip annotations (JNI safety)
-keepclasseswithmembers class * {
    native <methods>;
}
-keep @com.facebook.proguard.annotations.DoNotStrip class *
-keepclassmembers class * {
    @com.facebook.proguard.annotations.DoNotStrip *;
}
-keep @expo.modules.core.interfaces.DoNotStrip class *
-keepclassmembers class * {
    @expo.modules.core.interfaces.DoNotStrip *;
}

# Reanimated native runtime: JNI entry points and classes looked up by name.
# Also shipped as a consumer rule by the library; repeated here so the project
# rules stay self-documenting.
-keep class com.swmansion.reanimated.** { *; }

# Reanimated 4 runs worklets on the react-native-worklets runtime, which
# resolves worklet classes by name.
-keep class com.swmansion.worklets.** { *; }

# TurboModule interop used by Reanimated/worklets.
-keep class com.facebook.react.turbomodule.** { *; }

# Fabric renderer entry points referenced by the Reanimated/worklets JNI code.
-keep class com.facebook.react.fabric.** { *; }

# react-native-svg: JNI bridge + view classes.
-keep public class com.horcrux.svg.** { *; }

# react-native-gesture-handler: handlers and native views are instantiated from
# a name -> class registry.
-keep class com.swmansion.gesturehandler.** { *; }

# react-native-screens: fragments are recreated by the framework and native
# views are resolved by name.
-keep class com.swmansion.rnscreens.** { *; }

# react-native-safe-area-context: native view manager resolved by name.
-keep class com.th3rdwave.safeareacontext.** { *; }

# expo-sqlite: JNI bindings (expo-modules-core keeps Module subclasses but
# explicitly allows obfuscation, so keep the sqlite package's members).
-keep class expo.modules.sqlite.** { *; }
${MARKER_END}`;

/**
 * Sets/overwrites gradle properties while preserving every other entry.
 * `props` is the array shape used by `withGradleProperties`.
 */
function applyGradleProperties(props) {
  const next = props.map((item) =>
    item.type === 'property' && Object.prototype.hasOwnProperty.call(GRADLE_PROPERTIES, item.key)
      ? { ...item, value: GRADLE_PROPERTIES[item.key] }
      : item
  );

  for (const [key, value] of Object.entries(GRADLE_PROPERTIES)) {
    if (!next.some((item) => item.type === 'property' && item.key === key)) {
      next.push({ type: 'property', key, value });
    }
  }

  return next;
}

/**
 * Ensures build.gradle uses proguard-android-optimize.txt instead of proguard-android.txt
 * so that R8 optimization passes (inlining, class merging, argument removal) are fully active.
 */
function applyBuildGradleOptimizations(contents) {
  return contents.replace(
    /getDefaultProguardFile\(["']proguard-android\.txt["']\)/g,
    'getDefaultProguardFile("proguard-android-optimize.txt")'
  );
}

/**
 * Replaces the marked keep-rules block (or appends it the first time) without
 * touching the file's existing contents. Safe to run repeatedly.
 */
function applyProguardRules(contents) {
  const block = KEEP_RULES;
  const start = contents.indexOf(MARKER_START);
  const end = contents.indexOf(MARKER_END);

  if (start !== -1 && end !== -1 && end > start) {
    return contents.slice(0, start) + block + contents.slice(end + MARKER_END.length);
  }

  const trimmed = contents.replace(/\s*$/, '');
  return `${trimmed ? `${trimmed}\n\n` : ''}${block}\n`;
}

function withReleaseGradleProperties(config) {
  return withGradleProperties(config, (config) => {
    config.modResults = applyGradleProperties(config.modResults);
    return config;
  });
}

function withReleaseOptimizedBuildGradle(config) {
  return withAppBuildGradle(config, (config) => {
    if (config.modResults && config.modResults.contents) {
      config.modResults.contents = applyBuildGradleOptimizations(config.modResults.contents);
    }
    return config;
  });
}

function withReleaseProguardRules(config) {
  return withDangerousMod(config, [
    'android',
    async (config) => {
      const file = path.join(config.modRequest.platformProjectRoot, 'app', 'proguard-rules.pro');
      let contents = '';
      try {
        contents = await fs.promises.readFile(file, 'utf8');
      } catch {
        // First prebuild: the template may not have created the file yet.
      }
      await fs.promises.writeFile(file, applyProguardRules(contents), 'utf8');
      return config;
    },
  ]);
}

const STYLES_V35_CONTENT = `<resources xmlns:tools="http://schemas.android.com/tools">
  <!-- Android 15 (API 35+) enforces edge-to-edge by default.
       statusBarColor and navigationBarColor are deprecated on v35+, so they are omitted here. -->
  <style name="AppTheme" parent="Theme.AppCompat.DayNight.NoActionBar">
    <item name="android:editTextBackground">@drawable/rn_edit_text_material</item>
    <item name="colorPrimary">@color/colorPrimary</item>
  </style>
  <style name="Theme.App.SplashScreen" parent="Theme.SplashScreen">
    <item name="windowSplashScreenBackground">@color/splashscreen_background</item>
    <item name="windowSplashScreenAnimatedIcon">@drawable/splashscreen_logo</item>
    <item name="postSplashScreenTheme">@style/AppTheme</item>
    <item name="android:windowSplashScreenBehavior">icon_preferred</item>
  </style>
</resources>
`;

function withAndroid15EdgeToEdgeStyles(config) {
  return withDangerousMod(config, [
    'android',
    async (config) => {
      const dir = path.join(config.modRequest.platformProjectRoot, 'app', 'src', 'main', 'res', 'values-v35');
      await fs.promises.mkdir(dir, { recursive: true });
      await fs.promises.writeFile(path.join(dir, 'styles.xml'), STYLES_V35_CONTENT, 'utf8');
      return config;
    },
  ]);
}

module.exports = function withReleaseOptimizations(config) {
  config = withReleaseGradleProperties(config);
  config = withReleaseOptimizedBuildGradle(config);
  config = withReleaseProguardRules(config);
  config = withAndroid15EdgeToEdgeStyles(config);
  return config;
};

// Exported for local verification of the pure transforms.
module.exports.applyGradleProperties = applyGradleProperties;
module.exports.applyBuildGradleOptimizations = applyBuildGradleOptimizations;
module.exports.applyProguardRules = applyProguardRules;
module.exports.KEEP_RULES = KEEP_RULES;
module.exports.GRADLE_PROPERTIES = GRADLE_PROPERTIES;
